'use strict';
(() => {
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const money = n => (Number(n) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  const labels = { waiting: 'Aguardando pagamento', pending: 'Pagamento em análise', approved: 'Pagamento aprovado', rejected: 'Pagamento recusado', cancelled: 'Pagamento cancelado', expired: 'Prazo da reserva encerrado', refunded: 'Pagamento reembolsado', partially_refunded: 'Reembolso parcial', charged_back: 'Pagamento em contestação' };
  const resolutions = { paid_without_slot: 'O pagamento foi recebido, mas o horário não pôde ser confirmado. Entre em contato com o negócio para combinar outra data ou solicitar reembolso. Não pague novamente.', refund_required: 'O atendimento foi cancelado e o pagamento precisa ser resolvido com o profissional. Cancelar o horário não faz um reembolso automático.', duplicate_payment: 'Foi identificado mais de um pagamento para a mesma reserva. O profissional precisa conferir e resolver o valor adicional. Não pague novamente.', verification_required: 'Os dados do pagamento precisam de conferência pelo negócio. Nenhum horário será confirmado somente pela tela de retorno.', multiple_attempts_review: 'Foram identificadas várias tentativas de pagamento. O profissional precisa conferir todas antes de orientar outra cobrança. Não pague novamente.', chargeback_review: 'Existe uma contestação em acompanhamento. Entre em contato com o negócio para esclarecer a situação.' };
  function panel(p, zone, prefix = '', staff = false) {
    const action = name => `${prefix}${name}`, confirmed = ['confirmed', 'in_progress', 'completed', 'no_show'].includes(p.appointmentStatus);
    const title = p.resolution ? 'Este pagamento precisa de atenção' : p.state === 'approved' && confirmed ? 'Pagamento aprovado e horário confirmado' : labels[p.state] || 'Conferindo pagamento';
    return `<section class="card spaced payment-panel"><div class="eyebrow">${p.mode === 'sandbox' ? 'Teste · sem cobrança real' : 'Mercado Pago'}</div><h2 class="spaced">${esc(title)}</h2><p class="small muted spaced">${esc(p.serviceName)} · ${esc(p.professionalName)}<br>${esc(new Intl.DateTimeFormat('pt-BR', { timeZone: p.timeZone || zone, dateStyle: 'short', timeStyle: 'short' }).format(p.startAt))}</p><div class="summary-line spaced"><span>Valor do serviço</span><strong>${money(p.amountCents)}</strong></div><div class="summary-line"><span>Quem recebe</span><strong>${esc(p.receiver?.name || 'Profissional responsável')}</strong></div>${p.providerPaymentId ? `<p class="small muted spaced">Identificação no Mercado Pago: ${esc(p.providerPaymentId)}</p>` : ''}${p.resolution ? `<p class="note warning spaced">${esc(resolutions[p.resolution] || 'Entre em contato com o negócio para conferir esse pagamento.')}</p>` : ''}${p.appointmentStatus === 'awaiting_payment' && p.expiresAt > Date.now() ? `<p class="note spaced">Seu horário está reservado até ${esc(new Intl.DateTimeFormat('pt-BR', { timeZone: zone, dateStyle: 'short', timeStyle: 'short' }).format(p.expiresAt))}. A confirmação depende da aprovação do pagamento e da disponibilidade da reserva.</p>` : ''}${p.canPay ? `<p class="small muted spaced">O pagamento acontece no ambiente do Mercado Pago. Não informe dados de cartão ou senha nesta página.</p><div class="row spaced"><button type="button" class="button" data-action="${action('pay')}" data-id="${p.appointmentId}">${staff ? 'Gerar link para o cliente' : 'Continuar para o Mercado Pago'}</button></div>` : !confirmed && !p.resolution && !['refunded', 'partially_refunded', 'charged_back'].includes(p.state) ? '<p class="note warning spaced">O horário não está confirmado. Se você já pagou, atualize a situação antes de fazer outra tentativa ou entre em contato com o negócio.</p>' : ''}<div class="row spaced"><button type="button" class="button secondary" data-action="${action('payment-refresh')}" data-id="${p.appointmentId}">Atualizar situação</button></div>${staff ? '<p class="small muted spaced">Reembolsos e contestações são gerenciados na conta do profissional. Esta tela acompanha a situação informada pelo Mercado Pago.</p>' : ''}</section>`;
  }
  function safeRedirect(value) { const url = new URL(value); if (url.protocol !== 'https:' || !['sandbox.mercadopago.com.br', 'www.mercadopago.com.br', 'mercadopago.com.br'].includes(url.hostname) || url.username || url.password || url.port) throw new Error('O endereço do pagamento não pôde ser validado. Atualize a situação.'); return url.href; }
  window.RaelPayment = { panel, safeRedirect, labels };
})();
